<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { apiGet, apiPost, type ApiError } from './api/client'

type Session={accessToken:string;refreshToken:string;userEmail:string}
type Tenant={id:string;name:string;slug:string;status:string}
type Scope='GLOBAL'|'SELECTED'|'EXCLUSIVE'|'INTERNAL'
type Issue={path:string;code:string;message:string}
type Validation={valid:boolean;schema:string;contract_version:number;key?:string;name?:string;scope?:string;errors:Issue[];warnings:Issue[];surfaces:Record<string,{valid:boolean}>}
type Contract={name:string;schema:string;version:number;file_name_pattern:string;canonical_import_location:string;surfaces:Record<string,unknown>;scope_values:string[];example:Record<string,unknown>}
type ImportResult={key:string;name:string;scope:string;automatic_tenant_update:boolean;templates:Array<{surface:string;version_number:number;created:boolean;published:boolean}>}

const storageKey='scheduler-pro-admin-session'
const session=ref<Session|null>(null)
const open=ref(false)
const loading=ref(false)
const importing=ref(false)
const error=ref('')
const success=ref('')
const contract=ref<Contract|null>(null)
const tenants=ref<Tenant[]>([])
const fileName=ref('')
const bundleText=ref('')
const validation=ref<Validation|null>(null)
const scope=ref<Scope>('INTERNAL')
const exclusiveTenantId=ref('')
const selectedTenantIds=ref<string[]>([])
const publish=ref(false)
const updateExisting=ref(true)
const result=ref<ImportResult|null>(null)

const token=computed(()=>session.value?.accessToken||'')
const authenticated=computed(()=>Boolean(token.value))
const canImport=computed(()=>Boolean(validation.value?.valid)&&!importing.value&&(scope.value!=='EXCLUSIVE'||Boolean(exclusiveTenantId.value))&&(scope.value!=='SELECTED'||selectedTenantIds.value.length>0))

function readSession(){const raw=localStorage.getItem(storageKey);if(!raw){session.value=null;return}try{session.value=JSON.parse(raw) as Session}catch{session.value=null}}
function describe(exc:unknown,fallback:string){const value=exc as Partial<ApiError>;return value?.message||fallback}
function parseBundle():Record<string,unknown>{const value=JSON.parse(bundleText.value) as unknown;if(!value||typeof value!=='object'||Array.isArray(value))throw new Error('O arquivo precisa conter um objeto JSON.');return value as Record<string,unknown>}
function pretty(value:unknown){return JSON.stringify(value,null,2)}

async function loadContext(){loading.value=true;error.value='';try{const [contractData,tenantRows]=await Promise.all([apiGet<Contract>('/platform/templates/contract',token.value),apiGet<Tenant[]>('/platform/tenants',token.value)]);contract.value=contractData;tenants.value=tenantRows}catch(exc){error.value=describe(exc,'Não foi possível abrir a Central de Importação.')}finally{loading.value=false}}
async function openCenter(){readSession();if(!authenticated.value)return;open.value=true;await loadContext()}
function close(){open.value=false;error.value='';success.value=''}
async function onFile(event:Event){error.value='';success.value='';validation.value=null;result.value=null;const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;fileName.value=file.name;try{const text=await file.text();const parsed=JSON.parse(text);bundleText.value=pretty(parsed);await validateBundle()}catch(exc){error.value=exc instanceof Error?exc.message:'Arquivo JSON inválido.'}}
async function validateBundle(){error.value='';success.value='';result.value=null;try{const bundle=parseBundle();validation.value=await apiPost<Validation>('/platform/templates/import/validate',{bundle},token.value);if(validation.value.valid)success.value='Pacote válido. Escolha o destino e confirme a importação.'}catch(exc){validation.value=null;error.value=describe(exc,'Não foi possível validar o pacote.')}}
async function importBundle(){if(!canImport.value)return;importing.value=true;error.value='';success.value='';try{const bundle=parseBundle();result.value=await apiPost<ImportResult>('/platform/templates/import',{bundle,scope_override:scope.value,exclusive_tenant_id:scope.value==='EXCLUSIVE'?exclusiveTenantId.value:null,selected_tenant_ids:scope.value==='SELECTED'?selectedTenantIds.value:[],publish:publish.value,update_existing:updateExisting.value},token.value);success.value=`${result.value.templates.length} modelo(s) importado(s). Nenhuma página de cliente foi alterada automaticamente.`;window.dispatchEvent(new CustomEvent('scheduler-pro-template-catalog-changed'))}catch(exc){error.value=describe(exc,'Falha ao importar o pacote.')}finally{importing.value=false}}
function useExample(){if(!contract.value)return;fileName.value='modelo-negocio-generico.scheduler-pro-template.json';bundleText.value=pretty(contract.value.example);validation.value=null;result.value=null;void validateBundle()}
async function copyExample(){if(!contract.value)return;try{await navigator.clipboard.writeText(pretty(contract.value.example));success.value='Exemplo oficial copiado.'}catch{error.value='Não foi possível copiar automaticamente.'}}
function clearBundle(){fileName.value='';bundleText.value='';validation.value=null;result.value=null;error.value='';success.value=''}
function refreshSession(){const before=authenticated.value;readSession();if(!before&&authenticated.value&&open.value)void loadContext()}
onMounted(()=>{readSession();window.addEventListener('storage',refreshSession);window.addEventListener('scheduler-pro-admin-auth-changed',refreshSession)})
onUnmounted(()=>{window.removeEventListener('storage',refreshSession);window.removeEventListener('scheduler-pro-admin-auth-changed',refreshSession)})
</script>

<template>
  <button v-if="authenticated" class="template-import-launcher" type="button" @click="openCenter"><span>⇧</span><strong>Importar Modelos</strong></button>
  <div v-if="open&&authenticated" class="template-import-backdrop" @click.self="close">
    <section class="template-import-center" role="dialog" aria-modal="true" aria-label="Central de Importação de Modelos">
      <header class="import-header"><div><span>Scheduler Pro · Control Plane</span><h2>Central de Importação de Modelos</h2><p>Único ponto de entrada para novos modelos. O arquivo é validado antes de entrar na biblioteca.</p></div><button class="close" type="button" aria-label="Fechar" @click="close">×</button></header>
      <div v-if="loading" class="state">Carregando contrato de modelos…</div>
      <template v-else>
        <div class="contract-strip"><div><small>Contrato</small><strong>{{contract?.name}}</strong><span>{{contract?.schema}}</span></div><div><small>Arquivo padrão</small><strong>{{contract?.file_name_pattern}}</strong><span>Landing e Agendamento podem viajar no mesmo pacote.</span></div><div><small>Local oficial</small><strong>Control Plane</strong><span>Modelos & Suporte → Importar Modelos</span></div></div>
        <p v-if="error" class="alert error">{{error}}</p><p v-if="success" class="alert success">{{success}}</p>
        <div class="import-grid">
          <article class="card file-card"><div class="card-title"><div><span>1</span><strong>Pacote</strong></div><small>JSON validado pelo Scheduler Pro</small></div><label class="file-picker"><input type="file" accept="application/json,.json" @change="onFile"/><b>Escolher arquivo</b><span>{{fileName||'Nenhum arquivo selecionado'}}</span></label><div class="row-actions"><button type="button" @click="useExample">Usar exemplo oficial</button><button type="button" @click="copyExample">Copiar exemplo JSON</button><button v-if="bundleText" type="button" @click="clearBundle">Limpar</button></div><textarea v-model="bundleText" spellcheck="false" placeholder="Cole aqui um Scheduler Pro Template Package…" @input="validation=null;result=null"></textarea><button class="primary" type="button" :disabled="!bundleText" @click="validateBundle">Validar pacote</button></article>
          <article class="card validation-card"><div class="card-title"><div><span>2</span><strong>Validação</strong></div><small>Estrutura, renderer e página de agendamento</small></div><div v-if="!validation" class="empty">Escolha ou cole um pacote e clique em <b>Validar pacote</b>.</div><template v-else><div class="validation-status" :class="{ok:validation.valid,bad:!validation.valid}"><strong>{{validation.valid?'Pacote válido':'Pacote inválido'}}</strong><span>{{validation.key}} · {{validation.name}}</span></div><div class="surface-badges"><span v-for="(surface,key) in validation.surfaces" :key="key" :class="{ok:surface.valid}">{{String(key).toUpperCase()}} · {{surface.valid?'OK':'ERRO'}}</span></div><div v-if="validation.errors.length" class="issues"><strong>Erros</strong><div v-for="item in validation.errors" :key="`${item.path}-${item.code}`"><b>{{item.path}}</b><span>{{item.message}}</span><small>{{item.code}}</small></div></div><div v-if="validation.warnings.length" class="issues warning"><strong>Orientações</strong><div v-for="item in validation.warnings" :key="`${item.path}-${item.code}`"><b>{{item.path}}</b><span>{{item.message}}</span></div></div></template></article>
          <article class="card destination-card"><div class="card-title"><div><span>3</span><strong>Destino</strong></div><small>Nenhuma página em uso é trocada automaticamente</small></div><label>Disponibilidade<select v-model="scope"><option value="INTERNAL">Interno / ainda não publicado</option><option value="GLOBAL">Global para todos os clientes</option><option value="SELECTED">Somente clientes selecionados</option><option value="EXCLUSIVE">Exclusivo para um cliente</option></select></label><label v-if="scope==='EXCLUSIVE'">Cliente<select v-model="exclusiveTenantId"><option value="">Selecione</option><option v-for="tenant in tenants" :key="tenant.id" :value="tenant.id">{{tenant.name||tenant.slug}}</option></select></label><label v-if="scope==='SELECTED'">Clientes<select v-model="selectedTenantIds" multiple size="6"><option v-for="tenant in tenants" :key="tenant.id" :value="tenant.id">{{tenant.name||tenant.slug}}</option></select><small>Use Ctrl/Cmd para selecionar mais de um.</small></label><label class="check"><input v-model="publish" type="checkbox"/><span>Publicar esta versão na biblioteca imediatamente</span></label><label class="check"><input v-model="updateExisting" type="checkbox"/><span>Se a chave já existir, criar nova versão em vez de falhar</span></label><button class="primary" type="button" :disabled="!canImport" @click="importBundle">{{importing?'Importando…':'Importar modelos validados'}}</button><p class="safe-note">A importação cria ou versiona modelos. Para alterar um cliente, aplique o modelo pela área <b>Modelos & Suporte</b>; a versão atualmente publicada do cliente permanece intacta até essa ação.</p></article>
        </div>
        <article v-if="result" class="result-card"><strong>Importação concluída</strong><span>{{result.name}} · {{result.scope}}</span><div><em v-for="item in result.templates" :key="item.surface">{{item.surface}} v{{item.version_number}} · {{item.created?'novo':'nova versão'}} · {{item.published?'publicado':'rascunho'}}</em></div></article>
      </template>
    </section>
  </div>
</template>

<style scoped>
.template-import-launcher{position:fixed;right:22px;bottom:84px;z-index:2400;display:flex;align-items:center;gap:8px;min-height:42px;padding:0 15px;border:1px solid #dbe3ef;border-radius:14px;background:#fff;color:#10213b;box-shadow:0 14px 34px rgba(15,23,42,.14);cursor:pointer}.template-import-launcher span{display:grid;place-items:center;width:24px;height:24px;border-radius:8px;background:#e8f2ff;color:#1769e0;font-weight:900}.template-import-backdrop{position:fixed;inset:0;z-index:4600;padding:22px;background:rgba(10,22,42,.55);backdrop-filter:blur(8px);overflow:auto}.template-import-center{width:min(1280px,100%);margin:0 auto;border:1px solid #dbe3ef;border-radius:24px;background:#f6f8fc;color:#12203a;box-shadow:0 30px 100px rgba(2,8,23,.28);overflow:hidden}.import-header{display:flex;justify-content:space-between;gap:20px;padding:24px 26px;border-bottom:1px solid #e2e8f0;background:#fff}.import-header span{color:#2563eb;font-size:11px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}.import-header h2{margin:6px 0 5px;font-size:26px}.import-header p{margin:0;color:#52647c}.close{width:40px;height:40px;border:1px solid #dbe3ef;border-radius:12px;background:#fff;font-size:24px;cursor:pointer}.contract-strip{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;padding:18px 22px 0}.contract-strip>div{padding:14px;border:1px solid #e1e7ef;border-radius:16px;background:#fff}.contract-strip small,.contract-strip strong,.contract-strip span{display:block}.contract-strip small{color:#6b7b91;font-size:10px;font-weight:800;text-transform:uppercase}.contract-strip strong{margin:4px 0;color:#15243c}.contract-strip span{color:#607188;font-size:12px;line-height:1.45}.alert{margin:16px 22px 0;padding:12px 14px;border-radius:12px}.alert.error{background:#fff0f0;color:#a61b1b}.alert.success{background:#ecfdf3;color:#17653a}.import-grid{display:grid;grid-template-columns:1.08fr .95fr .9fr;gap:16px;padding:18px 22px 22px}.card,.result-card{border:1px solid #dfe6f0;border-radius:18px;background:#fff;padding:18px;min-width:0}.card-title{display:flex;justify-content:space-between;gap:10px;align-items:flex-start;margin-bottom:15px}.card-title>div{display:flex;align-items:center;gap:8px}.card-title>div span{display:grid;place-items:center;width:25px;height:25px;border-radius:8px;background:#edf4ff;color:#2563eb;font-weight:900}.card-title small{color:#718096;text-align:right}.file-picker{display:grid;grid-template-columns:auto 1fr;gap:5px 10px;align-items:center;padding:14px;border:1px dashed #aebdd1;border-radius:14px;background:#f8fbff;cursor:pointer}.file-picker input{display:none}.file-picker b{color:#1d63c7}.file-picker span{grid-column:1/-1;color:#607188;font-size:12px;overflow-wrap:anywhere}.row-actions{display:flex;flex-wrap:wrap;gap:7px;margin:10px 0}.row-actions button{border:1px solid #dbe3ef;border-radius:9px;background:#fff;padding:7px 9px;color:#43546c;cursor:pointer}.file-card textarea{width:100%;box-sizing:border-box;min-height:285px;resize:vertical;border:1px solid #dbe3ef;border-radius:12px;padding:12px;background:#0e1728;color:#dce8f9;font:12px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace}.primary{width:100%;min-height:44px;margin-top:10px;border:0;border-radius:12px;background:linear-gradient(135deg,#195fc7,#2388e9);color:#fff;font-weight:900;cursor:pointer}.primary:disabled{opacity:.45;cursor:not-allowed}.empty{padding:28px 12px;border:1px dashed #d5deea;border-radius:13px;color:#6b7b91;text-align:center;line-height:1.5}.validation-status{display:grid;gap:3px;padding:12px;border-radius:12px;background:#fff4f4;color:#a12525}.validation-status.ok{background:#edfbf3;color:#17653a}.surface-badges{display:flex;gap:7px;flex-wrap:wrap;margin:10px 0}.surface-badges span{padding:5px 8px;border-radius:999px;background:#fff1f1;color:#a12525;font-size:11px;font-weight:900}.surface-badges span.ok{background:#ecfdf3;color:#17653a}.issues{display:grid;gap:8px;margin-top:13px}.issues>strong{font-size:12px;text-transform:uppercase;color:#a12525}.issues>div{display:grid;gap:2px;padding:9px;border-left:3px solid #e15555;background:#fff7f7}.issues b{font-size:11px}.issues span{font-size:12px;color:#4e5d73}.issues small{color:#8a95a7}.issues.warning>strong{color:#9a6b0a}.issues.warning>div{border-left-color:#e3ae39;background:#fffaf0}.destination-card label{display:grid;gap:6px;margin:12px 0;color:#40516a;font-size:12px;font-weight:800}.destination-card select{min-height:42px;border:1px solid #dbe3ef;border-radius:10px;background:#fff;padding:8px;color:#182740}.destination-card select[multiple]{min-height:135px}.destination-card label small{color:#77869a;font-weight:500}.check{grid-template-columns:auto 1fr!important;align-items:center}.check input{width:16px;height:16px}.safe-note{margin:12px 0 0;padding:10px;border-radius:10px;background:#f3f7fc;color:#5a6c83;font-size:12px;line-height:1.5}.result-card{margin:0 22px 22px;display:grid;gap:5px}.result-card>span{color:#607188}.result-card>div{display:flex;gap:8px;flex-wrap:wrap;margin-top:5px}.result-card em{padding:6px 9px;border-radius:999px;background:#edf7ff;color:#245f9e;font-style:normal;font-size:11px;font-weight:800}.state{padding:60px;text-align:center;color:#617187}@media(max-width:1050px){.import-grid{grid-template-columns:1fr 1fr}.destination-card{grid-column:1/-1}.contract-strip{grid-template-columns:1fr 1fr}}@media(max-width:720px){.template-import-launcher{right:12px;bottom:74px}.template-import-backdrop{padding:8px}.template-import-center{border-radius:16px}.import-header{padding:18px}.import-header h2{font-size:22px}.contract-strip,.import-grid{grid-template-columns:1fr;padding-left:12px;padding-right:12px}.contract-strip>div,.destination-card{grid-column:auto}.card-title{display:grid}.card-title small{text-align:left}.file-card textarea{min-height:220px}}
</style>
